#include <stdio.h>

int sum(const int *values, int n)
{
    if (n == 0) {
        return 0;
    }
    return values[n - 1] + sum(values, n - 1);
}

int main(void)
{
    int values[] = {12, 24, 36};
    printf("%d\n", sum(values, 3));
    return 0;
}

#include <stdio.h>

int frames(int n)
{
    if (n == 0) {
        return 1;
    }
    return 1 + frames(n - 1);
}

int main(void)
{
    printf("%d\n", frames(3));
    return 0;
}

#include <stdio.h>

void unwind(int n)
{
    if (n > 0) {
        unwind(n - 1);
    }
    printf("%d", n);
}

int main(void)
{
    unwind(3);
    putchar('\n');
    return 0;
}
